import{_ as r}from"./plugin-vue_export-helper-c27b6911.js";import{r as o,o as t,c as i,f as l,b as a,d as e,a as s,e as c}from"./app-584b6577.js";const d={},p=a("h1",{id:"_10-apr-sol本位的套利方式",tabindex:"-1"},[a("a",{class:"header-anchor",href:"#_10-apr-sol本位的套利方式","aria-hidden":"true"},"#"),e(" 10% APR Sol本位的套利方式")],-1),h=a("p",null,"用借贷协议进行套利是一种比较古老的套利方式,当然也是相当安全,如果让抵押物和债务价格按照一定的比例同时增长或减少,那其实可以做到永远不被清算.",-1),_={href:"https://marginfi.com",target:"_blank",rel:"noopener noreferrer"},f=c(`<p>策略很简单:</p><p>将 Sol 质押到对应的质押节点获得质押权益代币,再将权益代币作为抵押品存入 Marginfi, 再借 Sol 重复这个过程.</p><p>在 Marginfi 中 Solana LTV 和 质押代币的Weight 基本都是在 90% 左右,所以理论上最终可以套娃 10 次这个过程,但最后几次就比较少了可以不做.</p><p>通过这种套利策略,可以在保持 SOL 本位的同时，获得 10% 以上稳定的年化收益率。</p><figure><img src="https://s21.ax1x.com/2025/04/25/pEoD9R1.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>例如在我的套利例子中,我的抵押物是 MRGN4(是 Marginfi 的质押权益代币),债务是 Solana,他们价格通常保持稳定,几乎不存在清算风险.</p><p>我的初始资金是 10 SOL,经过几次这样套娃后的每年可以有多少 Sol 呢?</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>(抵押物的利息 - 债务的利息)/Solana 价格
(4346.34*8.69% - 2658.25*7.58%)/152 ≈ 1.15
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>最终 10 SOL 的初始资金经过几次套娃后获得了 11.5% 左右的年化(原因是我只套了几层,并且没有将杠杆拉到最大).</p><h3 id="为什么有这么高的apr" tabindex="-1"><a class="header-anchor" href="#为什么有这么高的apr" aria-hidden="true">#</a> 为什么有这么高的APR?</h3><p>这个钱是从哪里赚的?很简单,Solana 每一笔交易费用有一半会被消费,另一半会给质押节点,所以我们质押节点的收益来自 Solana 网络上的每一笔交易费用,换句话说收益其实来自网络中的转账者.只要 Solana 网络还在持续运转就会有这样的套利机会.</p><p>其他的质押代币也存在这样的套利策略.</p><h3 id="会清算吗" tabindex="-1"><a class="header-anchor" href="#会清算吗" aria-hidden="true">#</a> 会清算吗?</h3><p>不会,因为抵押物是 Solana 的质押权益代币,其价格与 Solana 保持同步,所以说抵押物和债务的价格保持一定的关系,不存在清算风险.</p><p>Marginfi 协议被攻击/跑路?...这个倒是有可能.</p>`,15);function m(g,u){const n=o("ExternalLinkIcon");return t(),i("div",null,[p,h,l(" more "),a("p",null,[a("a",_,[e("MarginFi"),s(n)]),e("是 Solana 上的去中心化借贷协议,因为我对其比较熟悉所以就以其为例.")]),f])}const b=r(d,[["render",m],["__file","solana-arbitrage.html.vue"]]);export{b as default};
